#!/bin/bash
# === Auto-generated by claude-setup (Features: chrome) ===
LOG="$HOME/.claude-tmux-debug.log"
echo "=== $(date) ===" >> "$LOG"

SESSION="claude"

RAW_PATH="${1:-}"
if [ -z "$RAW_PATH" ] && [ -f "$HOME/.claude-launch-path" ]; then
    RAW_PATH=$(cat "$HOME/.claude-launch-path")
    rm -f "$HOME/.claude-launch-path"
fi
START_DIR="$HOME"

if [ -n "$RAW_PATH" ]; then
    if echo "$RAW_PATH" | grep -qi 'wsl.localhost'; then
        START_DIR=$(echo "$RAW_PATH" | sed 's|\\|/|g' | sed -E 's|^//wsl\.localhost/[^/]+||i')
    elif echo "$RAW_PATH" | grep -qE '^[A-Za-z]:'; then
        START_DIR=$(wslpath -u "$RAW_PATH" 2>/dev/null || echo "$HOME")
    elif [ -d "$RAW_PATH" ]; then
        START_DIR="$RAW_PATH"
    fi
fi

[ ! -d "$START_DIR" ] && START_DIR="$HOME"
echo "START_DIR=$START_DIR" >> "$LOG"

if tmux has-session -t "$SESSION" 2>/dev/null; then
    echo "Session exists, adding window" >> "$LOG"
    WIN_NAME="Claude-$(date +%H%M%S)"
    tmux new-window -t "$SESSION" -n "$WIN_NAME" -c "$START_DIR"
    tmux send-keys -t "$SESSION:$WIN_NAME" "cd '$START_DIR' && CLAUDE_CODE_EXPERIMENTAL_AGENT_TEAMS=1 /home/agent-workbench-user/.local/bin/claude --teammate-mode tmux --chrome" Enter
    tmux select-window -t "$SESSION:$WIN_NAME"
    echo "Attempting tmux attach..." >> "$LOG"
    exec tmux attach -t "$SESSION" 2>> "$LOG"
fi

echo "Creating new session" >> "$LOG"
tmux new-session -d -s "$SESSION" -c "$START_DIR" -n "Claude"

for i in $(seq 1 30); do
    tmux list-windows -t "$SESSION" 2>/dev/null | grep -q "Claude" && break
    sleep 0.1
done

tmux send-keys -t "$SESSION:Claude" "CLAUDE_CODE_EXPERIMENTAL_AGENT_TEAMS=1 /home/agent-workbench-user/.local/bin/claude --teammate-mode tmux --chrome" Enter

tmux new-window -t "$SESSION" -n "Console" -c "$START_DIR"
tmux select-pane -t "$SESSION:Console" -T "Console"
tmux select-window -t "$SESSION:Claude"
exec tmux attach -t "$SESSION" 2>> "$LOG"
